     1	/**
     2	 * Login page; reads the `next` search param.
     3	 *
     4	 * Owner D. Dynamic because it reads the session — an already-signed-in visitor
     5	 * is bounced straight to wherever they were heading rather than shown a form
     6	 * they do not need.
     7	 *
     8	 * Must call (do not reimplement): getSessionPrincipal
     9	 */
    10	
    11	import { redirect } from "next/navigation";
    12	import type { Metadata } from "next";
    13	import { getSessionPrincipal } from "@/lib/session";
    14	import { LoginForm } from "./login-form";
    15	
    16	type PageParams = Record<string, never>;
    17	
    18	export const dynamic = "force-dynamic";
    19	
    20	export const metadata: Metadata = {
    21	  title: "Sign in",
    22	};
    23	
    24	const DEFAULT_DESTINATION = "/orgs";
    25	
    26	export default async function Page(props: {
    27	  params: Promise<PageParams>;
    28	  searchParams: Promise<Record<string, string | string[] | undefined>>;
    29	}) {
    30	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
    31	  await props.params;
    32	  const search = await props.searchParams;
    33	
    34	  const next = safeDestination(search.next);
    35	
    36	  const principal = await getSessionPrincipal();
    37	  if (principal !== null) {
    38	    redirect(next);
    39	  }
    40	
    41	  return <LoginForm next={next} />;
    42	}
    43	
    44	/**
    45	 * Only same-site paths are honoured, so `?next=https://elsewhere` cannot turn
    46	 * the login form into an open redirect.
    47	 */
    48	function safeDestination(value: string | string[] | undefined): string {
    49	  const candidate = Array.isArray(value) ? value[0] : value;
    50	  if (typeof candidate !== "string") return DEFAULT_DESTINATION;
    51	  if (!candidate.startsWith("/") || candidate.startsWith("//")) {
    52	    return DEFAULT_DESTINATION;
    53	  }
    54	  return candidate;
    55	}
