     1	/**
     2	 * Turns the session cookie into an `Actor`. Everything server-side that needs authorization starts here.
     3	 *
     4	 * Must call (do not reimplement): assertOrgScope
     5	 */
     6	import { hashToken, randomToken } from "@/lib/hash";
     7	import { assertOrgScope } from "@/lib/tenant";
     8	import * as memberRepo from "@/server/repositories/member-repository";
     9	import * as orgRepo from "@/server/repositories/organization-repository";
