    84	 * removed member cannot pin their cookie to an org they left.
    85	 *
    86	 * `SessionPrincipal` carries no session id, so the write to `sessions.
    87	 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
    88	 * Action, which still holds the cookie. This method owns the authorization
    89	 * half of the switch.
    90	 */
    91	export async function switchActiveOrg(
    92	  principal: SessionPrincipal,
    93	  input: SwitchOrgInput,
    94	): Promise<void> {
    95	  const member = await memberRepo.findMember(input.orgId, principal.userId);
    96	  if (!member || member.status !== "active") {
    97	    throw new Error("You are not a member of that organization");
    98	  }
    99	
   100	  const orgs = await orgRepo.listOrgsForUser(principal.userId);
   101	  const target = orgs.find((org) => org.id === input.orgId);
   102	  if (!target) throw new Error("You are not a member of that organization");
   103	
   104	  assertOrgScope(
   105	    { userId: principal.userId, orgId: input.orgId, role: member.role },
   106	    target.id,
