    66	function isOwnedByActor(
    67	  actor: Actor,
    68	  resource: PermissionResource,
    69	): boolean {
    70	  switch (resource.kind) {
    71	    case "issue":
    72	      return (
    73	        resource.authorId === actor.userId ||
    74	        resource.assigneeId === actor.userId
    75	      );
    76	    case "comment":
    77	      return resource.authorId === actor.userId;
    78	    case "project":
    79	      return resource.leadId === actor.userId;
    80	    case "notification":
    81	      return resource.recipientId === actor.userId;
    82	    case "member":
    83	      return resource.targetUserId === actor.userId;
