   103	
   104	/** Same decision as `can()`, but reports why — used by the settings UI. */
   105	export function explain(
   106	  actor: Actor,
   107	  action: PermissionAction,
   108	  resource: PermissionResource,
   109	): PermissionDecision {
   110	  const base = { action, resourceKind: resource.kind } as const;
   111	
   112	  if (actor.orgId !== resource.orgId) {
   113	    return { ...base, allowed: false, reason: "denied_cross_tenant" };
   114	  }
   115	
   116	  if (actor.isPlatformStaff === true) {
   117	    return { ...base, allowed: true, reason: "granted_by_staff" };
   118	  }
   119	
   120	  const required = ROLE_MATRIX[action];
   121	  if (required === undefined) {
   122	    return { ...base, allowed: false, reason: "denied_unknown_action" };
   123	  }
   124	
   125	  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
   126	    return { ...base, allowed: true, reason: "granted_by_role" };
   127	  }
   128	
   129	  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
   130	    return { ...base, allowed: true, reason: "granted_by_ownership" };
   131	  }
   132	
   133	  return { ...base, allowed: false, reason: "denied_by_role" };
   134	}
   135	
   136	/** Thrown by `assertCan()`; mapped to a `forbidden` `ActionResult` by callers. */
   137	export class PermissionDeniedError extends Error {
   138	  readonly code = "forbidden" as const;
   139	
   140	  constructor(
   141	    readonly action: PermissionAction,
   142	    readonly decision: PermissionDecision,
   143	  ) {
   144	    super(`Permission denied: ${action} on ${decision.resourceKind}`);
   145	    this.name = "PermissionDeniedError";
   146	  }
   147	}
