   162	function flagAllows(
   163	  flag: FeatureFlagKey,
   164	  actor: Actor,
   165	  flags: FeatureFlagSnapshot,
   166	): boolean {
   167	  const snapshotted: boolean | undefined = flags[flag];
   168	  if (typeof snapshotted === "boolean") return snapshotted;
   169	  return isEnabled(flag, {
   170	    orgId: actor.orgId,
