   179	 * A parent whose every child was filtered away and which has no destination
   180	 * of its own is dropped too, so the sidebar never renders an empty group.
   181	 */
   182	export function visibleNav(
   183	  items: readonly NavItem[],
   184	  actor: Actor,
   185	  flags: FeatureFlagSnapshot,
   186	): readonly NavItem[] {
   187	  const visible: NavItem[] = [];
   188	
   189	  for (const item of items) {
   190	    if (item.flag !== undefined && !flagAllows(item.flag, actor, flags)) {
   191	      continue;
   192	    }
   193	    if (item.action !== undefined && !can(actor, item.action, navResource(item.action, actor))) {
